import { E2E_TEST_LICENSE_KEY_ID, E2E_TEST_LICENSE_PUBLIC_KEY } from "./e2e-test-trusted-key";

/** Chaves públicas autorizadas a assinar licenças de produção. */
export const DEFAULT_TRUSTED_KEYS: Record<string, string> = {
  // Production license trust root. Public key only; private key remains outside the repository.
  "clientix-license-2026-01": "-----BEGIN PUBLIC KEY-----\nMCowBQYDK2VwAyEABdvNnKrV2W9R1h047Ur/i8aovRQujYvxydKqjyxsIGI=\n-----END PUBLIC KEY-----",
};

/**
 * E2E builds may temporarily embed an ephemeral public key generated by
 * `scripts/e2e-build.sh`. The checked-in module is null and must stay that way;
 * no private test key is written to disk or included in the build.
 */
export function trustedKeysForBuild(): Record<string, string> {
  if (!E2E_TEST_LICENSE_PUBLIC_KEY) return DEFAULT_TRUSTED_KEYS;
  return {
    ...DEFAULT_TRUSTED_KEYS,
    [E2E_TEST_LICENSE_KEY_ID]: E2E_TEST_LICENSE_PUBLIC_KEY,
  };
}
